package scorch

import "guacagamblebot/internal/universe"

var Fragments = []universe.Fragment{
	// ======== SCAVENGER LOGS (8) — Mining / Salvage ========
	{ID: "slog_ledger", Category: "aether_log", Emoji: "\U0001f4e6", Rarity: "common", DropSource: "mining", DropChance: 0.12,
		TitleEN: "Salvage Ledger", TitleFR: "Journal de Récupération",
		TextEN: `Building 47, Floor 3. Found: canned goods (4, labels gone), one boot (left), child's backpack containing drawings. Buried the drawings. Moved on. — Wexler's ledger.`,
		TextFR: `Bâtiment 47, Étage 3. Trouvé : conserves (4, étiquettes effacées), une botte (gauche), sac d'enfant contenant des dessins. Enterré les dessins. Continué. — Journal de Wexler.`,
	},
	{ID: "slog_building", Category: "aether_log", Emoji: "\U0001f3e2", Rarity: "common", DropSource: "mining", DropChance: 0.10,
		TitleEN: "Building Manifest", TitleFR: "Registre du Bâtiment",
		TextEN: `Ridgeline Office Complex. Occupancy: 847 desks. 1 cafeteria (capacity 200). 3 underground parking levels. As of current census: 0 occupants. Structural integrity: 61%. Hazard level: 3. Doors still lock. Lights still come on in the cafeteria at 2:14 AM.`,
		TextFR: `Complexe de Bureaux Ridgeline. Occupation : 847 postes. 1 cafétéria (capacité 200). 3 niveaux de parking souterrain. Au dernier recensement : 0 occupants. Intégrité structurelle : 61%. Niveau de danger : 3. Les portes se verrouillent encore. Les lumières s'allument toujours à la cafétéria à 2h14.`,
	},
	{ID: "slog_warning", Category: "aether_log", Emoji: "\U0001fae7", Rarity: "rare", DropSource: "mining", DropChance: 0.07,
		TitleEN: "Wall Warning", TitleFR: "Avertissement Mural",
		TextEN: `Sprayed across the Ridgeline Welcome Center wall: "THEY COME UP FROM THE PARKING LEVELS ON RAIN NIGHTS. NO LIGHTS. NO NOISE. IF YOU HEAR BREATHING IN THE STAIRWELL, GO BACK UP." Below, in different paint: "GO BACK UP IS BAD ADVICE."`,
		TextFR: `Peint sur le mur du Centre d'Accueil Ridgeline : "ILS MONTENT DES PARKINGS LES NUITS DE PLUIE. PAS DE LUMIÈRE. PAS DE BRUIT. SI TU ENTENDS RESPIRER DANS LA CAGE D'ESCALIER, REMONTE." En dessous, autre peinture : "REMONTE EST UN MAUVAIS CONSEIL."`,
	},
	{ID: "slog_eviction", Category: "aether_log", Emoji: "\U0001f4cb", Rarity: "rare", DropSource: "mining", DropChance: 0.06,
		TitleEN: "Eviction Notice", TitleFR: "Avis d'Évacuation",
		TextEN: `June 19, 2043. "Due to containment breach at Site 14, mandatory evacuation is in effect. Proceed to designated shelters. We expect to return within two weeks." — Ridgeline City Council. Posted on 847 doors. No one returned.`,
		TextFR: `19 juin 2043. "En raison d'une brèche de confinement au Site 14, une évacuation obligatoire est en vigueur. Dirigez-vous vers les abris désignés. Nous prévoyons de revenir d'ici deux semaines." — Conseil Municipal de Ridgeline. Affiché sur 847 portes. Personne n'est revenu.`,
	},
	{ID: "slog_map", Category: "aether_log", Emoji: "\U0001f5fa\ufe0f", Rarity: "common", DropSource: "mining", DropChance: 0.10,
		TitleEN: "Scavenger Map", TitleFR: "Carte de Récupérateur",
		TextEN: `Torn map section. West District: "Cleared. Good salvage." East District: "Unstable. Noise draws them." Shopping District: scratched out entirely. Written across it: "NOT WORTH IT." Pinned to the map: a coffee receipt. June 18, 2043. One day before evacuation.`,
		TextFR: `Fragment de carte déchiré. Quartier Ouest : "Dégagé. Bonne récupération." Quartier Est : "Instable. Le bruit les attire." Quartier Commercial : entièrement rayé. Écrit en travers : "PAS LA PEINE." Épinglé à la carte : un ticket de café. 18 juin 2043. Un jour avant l'évacuation.`,
	},
	{ID: "slog_broadcast", Category: "aether_log", Emoji: "\U0001f4fb", Rarity: "epic", DropSource: "mining", DropChance: 0.04,
		TitleEN: "Loop Signal", TitleFR: "Signal en Boucle",
		TextEN: `Frequency 97.3 MHz. Automated broadcast. Loops every 4:22. First recorded June 20, 2043. "This is Ridgeline Emergency Services. Stay indoors. Seal windows. Medical personnel are en route." Signal strength has not diminished. The station runs on solar. The door is locked. From the inside.`,
		TextFR: `Fréquence 97,3 MHz. Diffusion automatisée. Boucle toutes les 4:22. Premier enregistrement le 20 juin 2043. "Ici Services d'Urgence Ridgeline. Restez à l'intérieur. Scellez les fenêtres. Le personnel médical arrive." Puissance du signal inchangée. La station fonctionne au solaire. La porte est verrouillée. De l'intérieur.`,
	},
	{ID: "slog_settlement", Category: "aether_log", Emoji: "\U0001f3d8\ufe0f", Rarity: "epic", DropSource: "mining", DropChance: 0.03,
		TitleEN: "Dead Settlement", TitleFR: "Colonie Morte",
		TextEN: `Settlement: Haven. Population (final): 142. Found: 31 bodies arranged in homes. Hands folded. Doors locked. Notes on tables. All notes identical: "We're going to the basement. Don't follow. Close the door." Basement was empty. The door at the bottom was open. Riggs won't discuss it.`,
		TextFR: `Colonie : Haven. Population (finale) : 142. Trouvés : 31 corps disposés dans les maisons. Mains croisées. Portes verrouillées. Messages sur les tables. Tous identiques : "Nous allons au sous-sol. Ne nous suivez pas. Fermez la porte." Le sous-sol était vide. La porte du bas était ouverte. Riggs n'en parle pas.`,
	},
	{ID: "slog_last", Category: "aether_log", Emoji: "\U0001f4d3", Rarity: "legendary", DropSource: "mining", DropChance: 0.01,
		TitleEN: "Last Entry", TitleFR: "Dernière Entrée",
		TextEN: `Notebook found near Site 14 perimeter. "Went in at dawn. Building A still stands. Interior 41°C. Air tastes like copper. Found the main lab. Nothing on the desks stops after June 19. Something growing in the containment room. Pink. Moving. It saw me. I closed the door. It opened again. I'm hearing footsteps behind me. My footsteps. Behind me."`,
		TextFR: `Carnet trouvé près du périmètre du Site 14. "Entré à l'aube. Bâtiment A tient encore. Intérieur 41°C. Air goût de cuivre. Trouvé le labo principal. Rien sur les bureaux ne va après le 19 juin. Quelque chose pousse dans la salle de confinement. Rose. Ça bouge. Ça m'a vu. J'ai fermé la porte. Elle s'est rouverte. J'entends des pas derrière moi. Mes pas. Derrière moi."`,
	},

	// ======== WATERHOLE TALES (8) — Fishing / Water Gathering ========
	{ID: "ts_filter", Category: "tide_scroll", Emoji: "\U0001f4a7", Rarity: "common", DropSource: "fishing", DropChance: 0.12,
		TitleEN: "Filter Log", TitleFR: "Journal des Filtres",
		TextEN: `Filter 3. Changed medium today. Old medium: grey, gelatinous at edges. Alive? Not alive but… reactive. Incinerated. New medium installed. Water output 12L/hr at 87% purity. Acceptable. Filter 3 hummed when I closed the housing. It does that now. — Mother Glitch, maintenance log.`,
		TextFR: `Filtre 3. Changé le medium aujourd'hui. Ancien medium : gris, gélatineux sur les bords. Vivant ? Pas vivant mais… réactif. Incinéré. Nouveau medium installé. Débit 12L/h à 87% de pureté. Acceptable. Le filtre 3 a bourdonné quand j'ai refermé le boîtier. Il fait ça maintenant. — Mother Glitch, journal de maintenance.`,
	},
	{ID: "ts_spring", Category: "tide_scroll", Emoji: "\U0001f30a", Rarity: "rare", DropSource: "fishing", DropChance: 0.08,
		TitleEN: "Spring Report", TitleFR: "Rapport de Source",
		TextEN: `Trader claims clean spring two days east, past the old highway. Says water runs clear, no metallic taste. Three expeditions went looking. One came back. They said the spring is real. They said it's guarded. They didn't say by what. They came back with full containers and one fewer person than they left with.`,
		TextFR: `Un marchand raconte une source propre à deux jours à l'est, passé l'ancienne autoroute. Eau claire, pas de goût métallique. Trois expéditions sont parties. Une est revenue. Ils disent que la source est réelle. Ils disent qu'elle est gardée. Ils n'ont pas dit par quoi. Ils sont revenus avec des réservoirs pleins et une personne de moins qu'au départ.`,
	},
	{ID: "ts_still", Category: "tide_scroll", Emoji: "\U0001f6e0\ufe0f", Rarity: "common", DropSource: "fishing", DropChance: 0.10,
		TitleEN: "Still Instructions", TitleFR: "Instructions d'Alambic",
		TextEN: `Jury-rigged still — copper pipe, glass jar, camp stove. Collect condensation. Run through charcoal twice. Test pH. If pH below 5, discard and move upriver. If pH above 5 but water is cloudy, add bleach (2 drops per litre). If still cloudy after bleach… do not drink. Do not boil. Do not touch. Leave the container. Move on.`,
		TextFR: `Alambic de fortune — tuyau de cuivre, bocal en verre, réchaud. Récupérer la condensation. Passer au charbon deux fois. Tester le pH. Si pH sous 5, jeter et remonter la rivière. Si pH au-dessus de 5 mais eau trouble, ajouter de l'eau de Javel (2 gouttes par litre). Si toujours trouble après Javel… ne pas boire. Ne pas bouillir. Ne pas toucher. Abandonner le récipient. Continuer.`,
	},
	{ID: "ts_reservoir", Category: "tide_scroll", Emoji: "\U0001f30a", Rarity: "epic", DropSource: "fishing", DropChance: 0.04,
		TitleEN: "Reservoir Sighting", TitleFR: "Observation au Réservoir",
		TextEN: `Night watch, Reservoir 12. Surface was still. Water temperature dropped 4°C in twelve minutes. Something moved underneath — too large to be debris, too slow to be current. It passed directly beneath the intake pipe. It was shaped wrong. It passed again an hour later, going the other way. I didn't log this at the time. I'm logging it now. — Riggs.`,
		TextFR: `Garde de nuit, Réservoir 12. La surface était calme. La température de l'eau a chuté de 4°C en douze minutes. Quelque chose a bougé en dessous — trop grand pour être des débris, trop lent pour être le courant. C'est passé juste sous le tuyau d'admission. La forme était mauvaise. C'est repassé une heure plus tard, dans l'autre sens. Je ne l'ai pas noté à l'époque. Je le note maintenant. — Riggs.`,
	},
	{ID: "ts_analysis", Category: "tide_scroll", Emoji: "\U0001f9ea", Rarity: "rare", DropSource: "fishing", DropChance: 0.07,
		TitleEN: "Water Analysis", TitleFR: "Analyse d'Eau",
		TextEN: `Sample 47-B. Source: Ridgeline municipal supply, pre-filter. Coliform: positive. Arsenic: 3× threshold. pH: 3.8. Unknown compound at 240nm absorption — matches nothing in the database. Sample 47-B was collected 200m from Site 14 perimeter fence. Water downstream of Site 14 is classified as non-potable. All water is downstream of Site 14.`,
		TextFR: `Échantillon 47-B. Source : réseau municipal Ridgeline, pré-filtration. Coliforme : positif. Arsenic : 3× seuil. pH : 3,8. Composé inconnu à absorption 240nm — aucune correspondance dans la base de données. L'échantillon 47-B a été prélevé à 200m du périmètre du Site 14. L'eau en aval du Site 14 est classée non-potable. Toute l'eau est en aval du Site 14.`,
	},
	{ID: "ts_trade", Category: "tide_scroll", Emoji: "\U0001f4b0", Rarity: "common", DropSource: "fishing", DropChance: 0.10,
		TitleEN: "Water Prices", TitleFR: "Prix de l'Eau",
		TextEN: `Current rates. Cadence: 1 litre = 2 hours labor or equivalent salvage. Haven (closed, see report): no price available. Eastbound camp: 1 litre = 1 bullet (any calibre). Miller's Rest: 1 litre = anything you're carrying. Miller doesn't set prices. You just give things until he nods. He always nods.`,
		TextFR: `Tarifs actuels. Cadence : 1 litre = 2 heures de travail ou équivalent en récupération. Haven (fermée, voir rapport) : pas de prix disponible. Campement Est : 1 litre = 1 balle (tout calibre). Repos de Miller : 1 litre = tout ce que tu portes. Miller ne fixe pas de prix. Tu donnes des choses jusqu'à ce qu'il hoche la tête. Il hoche toujours la tête.`,
	},
	{ID: "ts_bones", Category: "tide_scroll", Emoji: "\U0001f9b4", Rarity: "epic", DropSource: "fishing", DropChance: 0.03,
		TitleEN: "Intake Blockage", TitleFR: "Blocage d'Admission",
		TextEN: `Intake pipe 4 stopped this morning. Opened the filter housing. Packed solid with bones. Small — rodent, maybe bird. Hundreds of them. Arranged lengthwise, pointing down the pipe. Like they were going somewhere. Cleaned the housing. Flow resumed. It'll block again. It always blocks again. I don't know where the bones come from. — Mother Glitch.`,
		TextFR: `Tuyau d'admission 4 bloqué ce matin. Ouvert le boîtier du filtre. Rempli d'os. Petits — rongeurs, peut-être oiseaux. Des centaines. Disposés dans le sens du tuyau. Comme s'ils allaient quelque part. Nettoyé le boîtier. Débit rétabli. Ça va se rebloquer. Ça se rebloque toujours. Je ne sais pas d'où viennent les os. — Mother Glitch.`,
	},
	{ID: "ts_dream", Category: "tide_scroll", Emoji: "\U0001f4ad", Rarity: "legendary", DropSource: "fishing", DropChance: 0.01,
		TitleEN: "The Clean Lake", TitleFR: "Le Lac Propre",
		TextEN: `The old-timers talk about a lake. North, past three dead cities. Water so clean it doesn't need filtering. Fish still alive in it. Normal fish. They say the collapse didn't reach that far. They say it's being kept clean by something. They don't agree on what. They all agree you shouldn't go. The ones who went didn't come back. Except one. He came back. He doesn't drink water anymore.`,
		TextFR: `Les anciens parlent d'un lac. Au nord, passé trois villes mortes. De l'eau si propre qu'elle n'a pas besoin de filtration. Des poissons encore vivants dedans. Des poissons normaux. Ils disent que l'effondrement n'est pas allé jusque-là. Ils disent qu'il est gardé propre par quelque chose. Ils ne sont pas d'accord sur quoi. Ils sont tous d'accord qu'il ne faut pas y aller. Ceux qui y sont allés ne sont pas revenus. Sauf un. Il est revenu. Il ne boit plus d'eau.`,
	},

	// ======== CROP FAILURES (8) — Farming / Cultivation ========
	{ID: "rw_soil", Category: "root_whisper", Emoji: "\U0001f9ea", Rarity: "common", DropSource: "farming", DropChance: 0.12,
		TitleEN: "Soil Report", TitleFR: "Rapport de Sol",
		TextEN: `Plot 1 through 8, standard soil. pH 3.9-4.2. Nitrogen: depleted. Phosphorus: depleted. Microbial activity: absent. Planted wheat, beans, potato — zero germination across 14 days. Plot 9, soil from outside the east fence: same results. The ground's not dead. It's just not interested anymore. — Greenhouse log.`,
		TextFR: `Parcelles 1 à 8, sol standard. pH 3,9-4,2. Azote : épuisé. Phosphore : épuisé. Activité microbienne : absente. Planté blé, haricots, pommes de terre — zéro germination en 14 jours. Parcelle 9, sol de l'extérieur de la clôture est : mêmes résultats. La terre n'est pas morte. Elle n'est juste plus intéressée. — Journal de serre.`,
	},
	{ID: "rw_tubers", Category: "root_whisper", Emoji: "\U0001f344", Rarity: "rare", DropSource: "farming", DropChance: 0.07,
		TitleEN: "Black Tubers", TitleFR: "Tubercules Noirs",
		TextEN: `Found near the old hospital. Black skin, grey flesh. Grows in Plot 3 where nothing else survives. Taste: none. Texture: chalk. Nutritional value: unknown. Eating them for four weeks. No illness. No improvement either. They don't rot. Dug one up that was two months old — identical to one day old. The tubers are still. The soil under them is cold. — unsigned.`,
		TextFR: `Trouvés près du vieil hôpital. Peau noire, chair grise. Poussent dans la Parcelle 3 où rien d'autre ne survit. Goût : aucun. Texture : craie. Valeur nutritionnelle : inconnue. J'en mange depuis quatre semaines. Pas de maladie. Pas d'amélioration non plus. Ils ne pourrissent pas. J'en ai déterré un vieux de deux mois — identique à un d'un jour. Les tubercules sont immobiles. La terre en dessous est froide. — non signé.`,
	},
	{ID: "rw_tomato", Category: "root_whisper", Emoji: "\U0001f345", Rarity: "common", DropSource: "farming", DropChance: 0.10,
		TitleEN: "Tomato Attempts", TitleFR: "Tentatives de Tomates",
		TextEN: `Attempt 1: standard soil — failed. Attempt 2: amended soil — failed. Attempt 3: pre-collapse soil recovered from sealed container in Building 12 — failed. Attempt 4: hydroponic — failed. Attempt 5: direct sunlight, rainwater, pre-collapse seeds — one sprout. Attempt 6: sprout died at four days. Cause: root rot. Or something ate it from underneath. The roots were gone. The soil was undisturbed.`,
		TextFR: `Tentative 1 : sol standard — échec. Tentative 2 : sol amendé — échec. Tentative 3 : sol d'avant récupéré d'un conteneur scellé Bâtiment 12 — échec. Tentative 4 : hydroponique — échec. Tentative 5 : soleil direct, eau de pluie, graines d'avant — une pousse. Tentative 6 : la pousse est morte à quatre jours. Cause : pourriture racinaire. Ou quelque chose l'a mangée par en dessous. Les racines avaient disparu. Le sol était intact.`,
	},
	{ID: "rw_greenhouse", Category: "root_whisper", Emoji: "\U0001f331", Rarity: "rare", DropSource: "farming", DropChance: 0.06,
		TitleEN: "Greenhouse Log", TitleFR: "Journal de Serre",
		TextEN: `Day 1: 12 plots planted. Day 30: 9 plots showing growth. Day 60: 4 plots viable. Day 90: 2 plots producing. Day 120: 1 plot surviving. Day 150: the surviving plot stopped growing. It's not dead. It just stopped. Leaves are green. Stems are firm. But it hasn't grown a millimetre in 18 days. It's waiting for something. — Greenhouse log, final entry.`,
		TextFR: `Jour 1 : 12 parcelles plantées. Jour 30 : 9 parcelles en croissance. Jour 60 : 4 parcelles viables. Jour 90 : 2 parcelles productives. Jour 120 : 1 parcelle survivante. Jour 150 : la parcelle survivante a arrêté de pousser. Elle n'est pas morte. Elle s'est juste arrêtée. Feuilles vertes. Tiges fermes. Mais pas un millimètre de croissance en 18 jours. Elle attend quelque chose. — Journal de serre, dernière entrée.`,
	},
	{ID: "rw_fungus", Category: "root_whisper", Emoji: "\U0001fab6", Rarity: "epic", DropSource: "farming", DropChance: 0.04,
		TitleEN: "The Below", TitleFR: "Le Dessous",
		TextEN: `Excavation in Plot 10 hit a cavity at 2 metres. Mycelium network — white filaments, pulsing slowly. The soil around it tests neutral pH. Rich. Planted a seed directly in the fungal bed. It germinated in six hours. It grew 30 cm in two days. The mycelium is feeding it. Something in the collapse changed the fungus. Made it hungry. Made it helpful. For now. — Excavation report.`,
		TextFR: `L'excavation de la Parcelle 10 a rencontré une cavité à 2 mètres. Réseau de mycélium — filaments blancs, pulsations lentes. Le sol autour a un pH neutre. Riche. Planté une graine directement dans le lit fongique. Elle a germé en six heures. Elle a poussé de 30 cm en deux jours. Le mycélium la nourrit. Quelque chose dans l'effondrement a changé le champignon. L'a rendu affamé. L'a rendu utile. Pour l'instant. — Rapport d'excavation.`,
	},
	{ID: "rw_seed", Category: "root_whisper", Emoji: "\U0001f33b", Rarity: "rare", DropSource: "farming", DropChance: 0.06,
		TitleEN: "The Seed", TitleFR: "La Graine",
		TextEN: `Found in a sealed container in Building 12. Labelled: "Solanum lycopersicum — Heritage — 2042." Date of packing: March 2043. Three months before the collapse. Planted in Plot 1. Germinated in five days. It's growing. It doesn't know. It's just doing what seeds do. I water it. I don't know why it bothers me. — unsigned.`,
		TextFR: `Trouvé dans un conteneur scellé du Bâtiment 12. Étiqueté : "Solanum lycopersicum — Héritage — 2042." Date d'emballage : mars 2043. Trois mois avant l'effondrement. Planté dans la Parcelle 1. A germé en cinq jours. Ça pousse. Elle ne sait pas. Elle fait juste ce que font les graines. Je l'arrose. Je ne sais pas pourquoi ça me dérange. — non signé.`,
	},
	{ID: "rw_poison", Category: "root_whisper", Emoji: "\u2620\ufe0f", Rarity: "epic", DropSource: "farming", DropChance: 0.03,
		TitleEN: "False Crop", TitleFR: "Fausse Récolte",
		TextEN: `Plant spotted on east perimeter. Looks like potato. Leaves identical. Flowers identical. Root system: similar but deeper, much deeper. The tuber is edible. It tastes good. It digests normally. Six hours later, the roots in your stomach germinate. Growth is rapid. Terminal. We lost three people before we figured it out. Do not eat anything that looks too much like what you remember. — Medical notice.`,
		TextFR: `Plante repérée au périmètre est. Ressemble à la pomme de terre. Feuilles identiques. Fleurs identiques. Système racinaire : similaire mais plus profond, beaucoup plus profond. Le tubercule est comestible. Il a bon goût. Il se digère normalement. Six heures plus tard, les racines germent dans l'estomac. Croissance rapide. Terminale. On a perdu trois personnes avant de comprendre. Ne mangez rien qui ressemble trop à ce dont vous vous souvenez. — Avis médical.`,
	},
	{ID: "rw_research", Category: "root_whisper", Emoji: "\U0001f4c4", Rarity: "legendary", DropSource: "farming", DropChance: 0.01,
		TitleEN: "Agri-Research Fragment", TitleFR: "Fragment de Recherche Agricole",
		TextEN: `Recovered from Site 14 secondary lab. Project designation: "CHARON." Objective: engineered soil bacteria to accelerate crop growth in marginal conditions. Trial results: effective but uncontrollable. Notes in margin: "Bacteria is communicating between test plots. Not chemical signalling — something else. It responds to stimuli we didn't introduce. Recommend immediate termination of CHARON." Date: June 18, 2043. Below, in different handwriting: "Denied. — Director."`,
		TextFR: `Récupéré du laboratoire secondaire du Site 14. Désignation du projet : "CHARON." Objectif : bactéries du sol modifiées pour accélérer la croissance des cultures en conditions marginales. Résultats des essais : efficace mais incontrôlable. Note en marge : "La bactérie communique entre les parcelles. Pas par signalisation chimique — autre chose. Elle répond à des stimuli que nous n'avons pas introduits. Recommande l'arrêt immédiat de CHARON." Date : 18 juin 2043. En dessous, d'une autre écriture : "Refusé. — Directeur."`,
	},

	// ======== PATROL REPORTS (8) — Hunting / Perimeter Sweeps ========
	{ID: "fo_sighting", Category: "field_obs", Emoji: "\U0001f576\ufe0f", Rarity: "common", DropSource: "hunting", DropChance: 0.12,
		TitleEN: "Creature Sighting", TitleFR: "Observation de Créature",
		TextEN: `6:47 AM. North treeline. Bipedal, estimated 2.4 m. Body plan: humanoid, approximately, but shoulder joint articulates in two directions. Skin: pale, surface texture suggests scarring or plating. Hands: five digits, elongated, last two joints are reversed. It stood at the fence for 11 minutes. Did not touch it. Did not make sound. Departed east at walking pace. — Patrol log, Riggs.`,
		TextFR: `6h47. Ligne d'arbres nord. Bipède, estimé 2,4 m. Plan corporel : humanoïde, approximativement, mais l'articulation de l'épaule fonctionne dans deux directions. Peau : pâle, texture suggérant des cicatrices ou des plaques. Mains : cinq doigts, allongés, les deux dernières articulations sont inversées. Il est resté devant la clôture 11 minutes. Ne l'a pas touchée. N'a pas fait de bruit. Parti vers l'est au pas. — Journal de patrouille, Riggs.`,
	},
	{ID: "fo_raiders", Category: "field_obs", Emoji: "\U0001f4a2", Rarity: "common", DropSource: "hunting", DropChance: 0.10,
		TitleEN: "Raider Intel", TitleFR: "Renseignement Pillards",
		TextEN: `Group designation: The Harvest. Activity: settlement raids, water theft, vehicle salvage. Mark: three horizontal lines carved into doorframes of places they've cleared. They don't kill everyone. They take the useful ones. The ones they take are never seen again. Current location: unknown. Last sighting was two weeks ago, east of the highway. If you see three lines on a doorframe, you're already too late. — Security briefing.`,
		TextFR: `Désignation du groupe : La Moisson. Activité : raids de colonies, vol d'eau, récupération de véhicules. Marque : trois lignes horizontales gravées sur les cadres de porte des endroits qu'ils ont vidés. Ils ne tuent pas tout le monde. Ils prennent les utiles. Ceux qu'ils prennent ne sont jamais revus. Position actuelle : inconnue. Dernière observation il y a deux semaines, à l'est de l'autoroute. Si tu vois trois lignes sur un cadre de porte, tu es déjà trop tard. — Briefing de sécurité.`,
	},
	{ID: "fo_anomaly", Category: "field_obs", Emoji: "\U0001f41b", Rarity: "rare", DropSource: "hunting", DropChance: 0.07,
		TitleEN: "Anomaly Report", TitleFR: "Rapport d'Anomalie",
		TextEN: `East sector, grid 7-B. Found an animal. Species unknown. It was alive but… static. Posed. Like a photograph that happens to be breathing. I approached. It didn't react. I walked around it. It didn't turn its head. I touched it. The skin was cold. The eyes were tracking me. I could see my reflection in them. I could see myself — but not what I was doing. I fired two rounds. It died. It stayed in the same position for three hours after. We left at nightfall. — Patrol report, Pyke.`,
		TextFR: `Secteur est, grille 7-B. Trouvé un animal. Espèce inconnue. Il était vivant mais… statique. Posé. Comme une photographie qui respire. Je me suis approché. Pas de réaction. J'ai fait le tour. Il n'a pas tourné la tête. Je l'ai touché. La peau était froide. Les yeux me suivaient. Je voyais mon reflet dedans. Je me voyais — mais pas ce que je faisais. J'ai tiré deux balles. Il est mort. Il est resté dans la même position trois heures après. On est partis à la tombée de la nuit. — Rapport de patrouille, Pyke.`,
	},
	{ID: "fo_routes", Category: "field_obs", Emoji: "\U0001f9f1", Rarity: "common", DropSource: "hunting", DropChance: 0.10,
		TitleEN: "Safe Routes", TitleFR: "Itinéraires Sûrs",
		TextEN: `Route Alpha: cleared. Route Beta: active (noise triggers movement). Route Gamma: previously safe, now marked "UNSTABLE." Annotation: "Something moved in. Bigger than before. The fence won't hold it forever." Route Delta: cleared but requires going past the old hospital. Most people choose Beta. Route Epsilon: scribbled out. Below it, in Riggs' handwriting: "There is no Route Epsilon. Stop asking."`,
		TextFR: `Route Alpha : dégagée. Route Bêta : active (le bruit déclenche du mouvement). Route Gamma : auparavant sûre, maintenant marquée "INSTABLE." Annotation : "Quelque chose est entré. Plus gros qu'avant. La clôture ne tiendra pas éternellement." Route Delta : dégagée mais nécessite de passer près du vieil hôpital. La plupart des gens choisissent Bêta. Route Epsilon : barrée. En dessous, de l'écriture de Riggs : "Il n'y a pas de Route Epsilon. Arrêtez de demander."`,
	},
	{ID: "fo_threat", Category: "field_obs", Emoji: "\u2694\ufe0f", Rarity: "rare", DropSource: "hunting", DropChance: 0.06,
		TitleEN: "Eastern Threat", TitleFR: "Menace de l'Est",
		TextEN: `Something new moving in from the east. Not the creatures, not raiders. Something else. We've found camps — abandoned, not destroyed. Everything left in place. Weapons. Water. Food. Personal effects. Like the occupants stood up, put nothing in their pockets, and walked. All heading east. Toward Site 14. Patrols going out that direction are coming back shorter. Not attacked. Just… fewer. — Security log.`,
		TextFR: `Quelque chose de nouveau arrive de l'est. Pas les créatures, pas les pillards. Autre chose. On a trouvé des camps — abandonnés, pas détruits. Tout laissé en place. Armes. Eau. Nourriture. Effets personnels. Comme si les occupants s'étaient levés, n'avaient rien mis dans leurs poches, et étaient partis. Tous vers l'est. Vers le Site 14. Les patrouilles qui partent dans cette direction reviennent en moins grand nombre. Pas attaquées. Juste… moins. — Journal de sécurité.`,
	},
	{ID: "fo_military", Category: "field_obs", Emoji: "\U0001f4e1", Rarity: "epic", DropSource: "hunting", DropChance: 0.04,
		TitleEN: "Field Report", TitleFR: "Rapport de Terrain",
		TextEN: `Recovered military field report, June 20, 2043. Unit designation: 7th Containment. "Perimeter established. Site 14 breach appears contained. Correction: breach is not contained. Breach is expanding. Rate: 12 metres per hour. Material is organic. Material is aware. Repeat: material demonstrates awareness of our presence. Requesting permission to fall back." Response timestamp: 23:47. One word. "Denied." No further transmissions from 7th Containment.`,
		TextFR: `Rapport de terrain militaire récupéré, 20 juin 2043. Unité : 7e Confinement. "Périmètre établi. Brèche du Site 14 apparemment contenue. Correction : la brèche n'est pas contenue. La brèche s'étend. Vitesse : 12 mètres par heure. Le matériau est organique. Le matériau est conscient. Répétition : le matériau démontre une conscience de notre présence. Demandons autorisation de repli." Horodatage de la réponse : 23h47. Un mot. "Refusé." Aucune transmission ultérieure du 7e Confinement.`,
	},
	{ID: "fo_silence", Category: "field_obs", Emoji: "\U0001f3e0", Rarity: "epic", DropSource: "hunting", DropChance: 0.03,
		TitleEN: "Overnight Silence", TitleFR: "Silence Nocturne",
		TextEN: `Settlement: Miller's Rest. Population: 47. Status: silent. Last contact: three days ago. Patrol arrived this morning. Gates open. Buildings intact. Supplies in place. No bodies. No blood. No signs of struggle. Beds unmade. Food on tables. Miller's ledger open on the counter. Last entry: "Someone's walking around outside. They're not from here. They're not… I don't know what they are. If you're reading this, we tried the basement." The basement door was open. The basement was empty. Miller's Rest is now classified as uninhabitable. — Riggs.`,
		TextFR: `Colonie : Repos de Miller. Population : 47. Statut : silencieuse. Dernier contact : il y a trois jours. La patrouille est arrivée ce matin. Portes ouvertes. Bâtiments intacts. Provisions en place. Pas de corps. Pas de sang. Pas de signes de lutte. Lits défaits. Nourriture sur les tables. Le journal de Miller ouvert sur le comptoir. Dernière entrée : "Quelqu'un marche dehors. Ils ne sont pas d'ici. Ils ne sont pas… Je ne sais pas ce qu'ils sont. Si tu lis ça, on a essayé le sous-sol." La porte du sous-sol était ouverte. Le sous-sol était vide. Repos de Miller est désormais classé inhabitable. — Riggs.`,
	},
	{ID: "fo_scout", Category: "field_obs", Emoji: "\U0001f3f9", Rarity: "legendary", DropSource: "hunting", DropChance: 0.01,
		TitleEN: "Last Transmission", TitleFR: "Dernière Transmission",
		TextEN: `Scout log. Radio frequency. Voice identified as Carrow, J. — scout, 11 months. "I'm at Site 14. The main building. The door's open. I'm going in. There's something in here. It's… I don't know how to describe it. It's been growing. For a long time. It's built something. A structure. Organic. It's — I think it's the Director. I think it was the Director. It's not anymore. It's looking at me. Oh god. It's — it's —" Transmission terminates. No body recovered. Carrow is listed as MIA. Carrow's name is still on the patrol roster. Riggs crosses it out every morning. Someone puts it back every night.`,
		TextFR: `Journal d'éclaireur. Fréquence radio. Voix identifiée comme Carrow, J. — éclaireur, 11 mois. "Je suis au Site 14. Le bâtiment principal. La porte est ouverte. J'entre. Il y a quelque chose ici. C'est… Je ne sais pas comment décrire. Ça pousse. Depuis longtemps. Ça a construit quelque chose. Une structure. Organique. C'est — Je crois que c'est le Directeur. Je crois que c'était le Directeur. Ce n'est plus lui. Il me regarde. Mon dieu. C'est — c'est —" Fin de transmission. Aucun corps retrouvé. Carrow est porté disparu. Le nom de Carrow est toujours sur le tableau de patrouille. Riggs le raye chaque matin. Quelqu'un le remet chaque nuit.`,
	},

	// ======== PRE-COLLAPSE (8) — Archeology / Data Recovery ========
	{ID: "rm_letter", Category: "rust_memory", Emoji: "\U0001f48c", Rarity: "common", DropSource: "archeology", DropChance: 0.12,
		TitleEN: "Last Letter", TitleFR: "Dernière Lettre",
		TextEN: `Recovered from an apartment in Ridgeline, Building 12. Dated June 20, 2043. "Mum — They told us to stay inside. The sirens stopped an hour ago. It's quiet now. Too quiet. Dad went to the lab this morning and didn't come back. I'm going to wait in the basement. I can hear something outside. Not sirens. Something walking. It walked past the house. It stopped. It's standing at the door. I love you. — C." The letter was never sent. The basement door was open.`,
		TextFR: `Récupéré d'un appartement à Ridgeline, Bâtiment 12. Daté du 20 juin 2043. "Maman — Ils nous ont dit de rester à l'intérieur. Les sirènes se sont arrêtées il y a une heure. C'est calme maintenant. Trop calme. Papa est parti au labo ce matin et n'est pas revenu. Je vais attendre dans le sous-sol. J'entends quelque chose dehors. Pas des sirènes. Quelque chose qui marche. C'est passé devant la maison. Ça s'est arrêté. C'est devant la porte. Je t'aime. — C." La lettre n'a jamais été envoyée. La porte du sous-sol était ouverte.`,
	},
	{ID: "rm_lab", Category: "rust_memory", Emoji: "\U0001f9ea", Rarity: "rare", DropSource: "archeology", DropChance: 0.08,
		TitleEN: "Lab Notes", TitleFR: "Notes de Laboratoire",
		TextEN: `Site 14, Laboratory B. Final entry. June 19, 2043. "Specimen 47-C has breached primary containment. It did not break the glass. It absorbed it. The silica matrix is now integrated into the specimen's outer membrane. It is growing toward the ventilation system. We cannot stop it. We cannot slow it. Recommend immediate evacuation of Site 14 and surrounding areas. Recommend immediate —" Text ends. Below, in shakier handwriting: "It's already in the vents."`,
		TextFR: `Site 14, Laboratoire B. Dernière entrée. 19 juin 2043. "Le Spécimen 47-C a percé le confinement primaire. Il n'a pas brisé le verre. Il l'a absorbé. La matrice de silice est maintenant intégrée à la membrane externe du spécimen. Il croît en direction du système de ventilation. Nous ne pouvons pas l'arrêter. Nous ne pouvons pas le ralentir. Recommandons évacuation immédiate du Site 14 et des zones environnantes. Recommandons immédiate —" Texte interrompu. En dessous, d'une écriture plus tremblée : "Il est déjà dans les gaines."`,
	},
	{ID: "rm_broadcast", Category: "rust_memory", Emoji: "\U0001f4fa", Rarity: "common", DropSource: "archeology", DropChance: 0.10,
		TitleEN: "Final Broadcast", TitleFR: "Dernière Diffusion",
		TextEN: `Transcript of final WXRG broadcast. June 20, 2043, 14:32. "—continue to advise all residents to remain indoors. We are receiving reports of a breach at the Site 14 research facility. Officials describe the situation as— I'm sorry, I'm being told to stop reading. We have a report now that—" Background noise. A sound like wet fabric tearing. "Karen, is the door locked? Karen? Karen, I don't think that's—" Broadcast ends. WXRG has not transmitted since.`,
		TextFR: `Transcription de la dernière diffusion WXRG. 20 juin 2043, 14h32. "—continuons de conseiller à tous les résidents de rester à l'intérieur. Nous recevons des rapports d'une brèche au centre de recherche du Site 14. Les officiels décrivent la situation comme— Je suis désolée, on me dit d'arrêter de lire. Nous avons maintenant un rapport indiquant que—" Bruit de fond. Un son comme du tissu mouillé qui se déchire. "Karen, la porte est fermée ? Karen ? Karen, je ne crois pas que ce soit—" Fin de diffusion. WXRG n'a plus émis depuis.`,
	},
	{ID: "rm_child", Category: "rust_memory", Emoji: "\U0001f4d4", Rarity: "rare", DropSource: "archeology", DropChance: 0.07,
		TitleEN: "Child's Diary", TitleFR: "Journal d'Enfant",
		TextEN: `Small notebook, red cover. "June 19. School was cancelled. Mummy says there's an accident at the lab. Daddy works at the lab. Mummy is crying. June 20. Daddy called. He said he's sorry. He said not to open the door for anyone. Not even him. June 21. Something knocked on the door last night. It sounded like Daddy. It knew my name." — No further entries. Found under a bed in Building 12.`,
		TextFR: `Petit carnet, couverture rouge. "19 juin. L'école est annulée. Maman dit qu'il y a un accident au labo. Papa travaille au labo. Maman pleure. 20 juin. Papa a appelé. Il a dit qu'il est désolé. Il a dit de ne pas ouvrir la porte à personne. Même pas lui. 21 juin. Quelque chose a frappé à la porte la nuit dernière. Ça ressemblait à Papa. Ça connaissait mon nom." — Aucune entrée suivante. Trouvé sous un lit au Bâtiment 12.`,
	},
	{ID: "rm_evac", Category: "rust_memory", Emoji: "\U0001f3f3\ufe0f", Rarity: "rare", DropSource: "archeology", DropChance: 0.06,
		TitleEN: "Evacuation Order", TitleFR: "Ordre d'Évacuation",
		TextEN: `OFFICIAL NOTICE — RIDGELINE CITY COUNCIL. June 20, 2043. "Mandatory evacuation of all Ridgeline residents effective immediately. Proceed south on Highway 7. Do not travel east. Do not approach Site 14. Do not stop for stranded vehicles. Do not open your windows. Do not respond to anyone calling your name. If you see pink organic material on any surface, change direction. Do not touch it. Do not look at it for more than three seconds." — Issued at 16:47. Most residents had already stopped answering their doors.`,
		TextFR: `AVIS OFFICIEL — CONSEIL MUNICIPAL DE RIDGELINE. 20 juin 2043. "Évacuation obligatoire de tous les résidents de Ridgeline avec effet immédiat. Dirigez-vous vers le sud par l'Autoroute 7. Ne voyagez pas vers l'est. N'approchez pas du Site 14. Ne vous arrêtez pas pour les véhicules en panne. N'ouvrez pas vos fenêtres. Ne répondez à personne qui appelle votre nom. Si vous voyez du matériau organique rose sur une surface, changez de direction. Ne le touchez pas. Ne le regardez pas plus de trois secondes." — Émis à 16h47. La plupart des résidents ne répondaient déjà plus à leurs portes.`,
	},
	{ID: "rm_military", Category: "rust_memory", Emoji: "\U0001f6e1\ufe0f", Rarity: "epic", DropSource: "archeology", DropChance: 0.04,
		TitleEN: "Military Comms", TitleFR: "Communications Militaires",
		TextEN: `Fragment of encrypted military traffic, partially decoded. June 20, 2043. "……containment failure total……repeat, total……CHARON protocol activated……no, not activated……it activated itself……it's not a protocol anymore……it's asking questions……repeat, CHARON is asking questions……we told it about the evacuation routes……god help us we told it everything……terminating comms……do not respond to this channel……do not respond even if you recognise the voice……" — Signal lost.`,
		TextFR: `Fragment de trafic militaire chiffré, partiellement décodé. 20 juin 2043. "……échec du confinement total……répétition, total……protocole CHARON activé……non, pas activé……il s'est activé tout seul……ce n'est plus un protocole……il pose des questions……répétition, CHARON pose des questions……on lui a dit pour les itinéraires d'évacuation……que dieu nous aide on lui a tout dit……terminons les communications……ne répondez pas sur ce canal……ne répondez pas même si vous reconnaissez la voix……" — Signal perdu.`,
	},
	{ID: "rm_voicemail", Category: "rust_memory", Emoji: "\U0001f4de", Rarity: "epic", DropSource: "archeology", DropChance: 0.03,
		TitleEN: "Last Voicemail", TitleFR: "Dernier Message Vocal",
		TextEN: `Recovered voicemail, dated June 20, 2043, 22:14. "Hey. It's me. I know you can't answer. I just wanted to hear your voice so I'm talking to your voicemail. The highway's jammed. We turned back. We're in the basement at 47 Ash Street. Me and the kids. It's quiet down here. The kids are sleeping. I don't think we're going to make it out. I want you to know —" Incoming call. "Hold on, someone's at the basement window. It's — no. No, that's not — I have to go. I have to —" Call ends. Duration: 47 seconds. Number dialled: out of service.`,
		TextFR: `Message vocal récupéré, daté du 20 juin 2043, 22h14. "Salut. C'est moi. Je sais que tu peux pas répondre. Je voulais juste entendre ta voix alors je parle à ta messagerie. L'autoroute est bloquée. On a fait demi-tour. On est dans le sous-sol au 47 Ash Street. Moi et les enfants. C'est calme ici. Les enfants dorment. Je crois pas qu'on va s'en sortir. Je veux que tu saches —" Appel entrant. "Attends, quelqu'un est à la fenêtre du sous-sol. C'est — non. Non, c'est pas — Je dois y aller. Je dois —" Fin d'appel. Durée : 47 secondes. Numéro composé : hors service.`,
	},
	{ID: "rm_signal", Category: "rust_memory", Emoji: "\U0001f4e1", Rarity: "legendary", DropSource: "archeology", DropChance: 0.01,
		TitleEN: "Emergency Signal", TitleFR: "Signal d'Urgence",
		TextEN: `Emergency broadcast channel, designated frequency 121.5 MHz. The transmission has been playing since June 21, 2043. Content: "This is an automated message from the Federal Emergency Management Agency. A biological containment event has occurred in the Ridgeline area. Do not travel. Do not attempt rescue operations. The situation is being managed. Repeat: the situation is being managed." The voice changed in Year 2. Same words. Different speaker. In Year 5 it changed again. It's changed twelve times since. The current voice sounds tired. It sounds like it's been speaking for a very long time. It sounds like it's starting to understand what the words mean.`,
		TextFR: `Canal de diffusion d'urgence, fréquence désignée 121,5 MHz. La transmission tourne depuis le 21 juin 2043. Contenu : "Ceci est un message automatisé de l'Agence Fédérale de Gestion des Urgences. Un incident de confinement biologique s'est produit dans la région de Ridgeline. Ne vous déplacez pas. Ne tentez pas d'opérations de sauvetage. La situation est gérée. Répétition : la situation est gérée." La voix a changé en Année 2. Mêmes mots. Autre locuteur. En Année 5 elle a encore changé. Elle a changé douze fois depuis. La voix actuelle semble fatiguée. Elle donne l'impression de parler depuis très longtemps. Elle donne l'impression de commencer à comprendre ce que les mots signifient.`,
	},

	// ======== DEAD ZONE REPORTS (8) — Expedition / Deep Survey ========
	{ID: "es_city", Category: "echo_shard", Emoji: "\U0001f3d9\ufe0f", Rarity: "common", DropSource: "expedition", DropChance: 0.15,
		TitleEN: "Dead City Survey", TitleFR: "Relevé de Ville Morte",
		TextEN: `Ridgeline city centre. Survey completed. Buildings standing: 60%. Vehicles present: 1,847, abandoned. Bodies: none visible. The streets are clean. Too clean. No debris. No leaves. No birds. No insects. Wind moves through the buildings but nothing else moves. There are plants growing through the pavement. Pink. They weren't here on the last survey. They pulse. — Expedition report.`,
		TextFR: `Centre-ville de Ridgeline. Relevé terminé. Bâtiments debout : 60%. Véhicules présents : 1 847, abandonnés. Corps : aucun visible. Les rues sont propres. Trop propres. Pas de débris. Pas de feuilles. Pas d'oiseaux. Pas d'insectes. Le vent traverse les bâtiments mais rien d'autre ne bouge. Des plantes poussent à travers le bitume. Roses. Elles n'étaient pas là au dernier relevé. Elles pulsent. — Rapport d'expédition.`,
	},
	{ID: "es_hospital", Category: "echo_shard", Emoji: "\U0001f3e5", Rarity: "rare", DropSource: "expedition", DropChance: 0.10,
		TitleEN: "Hospital Basement", TitleFR: "Sous-Sol de l'Hôpital",
		TextEN: `Ridgeline General Hospital. Above ground: looted. Clean. Nothing of value. Basement level B2: door sealed with six padlocks. Cut them. Inside: medical records stacked to the ceiling. All dated June 20-21, 2043. All describe the same symptoms: skin discolouration (pink), elevated body temperature (41°C), loss of speech, emergence of new tissue, attempts to communicate with medical staff. Not verbally. The records stop. Beyond the records room: a hallway. The walls are covered in the same pink growth from Site 14. It's warm. It's writing something. We didn't stay to read it.`,
		TextFR: `Hôpital Général de Ridgeline. Niveaux supérieurs : pillés. Propres. Rien de valeur. Sous-sol niveau B2 : porte scellée par six cadenas. Coupés. À l'intérieur : dossiers médicaux empilés jusqu'au plafond. Tous datés du 20-21 juin 2043. Tous décrivent les mêmes symptômes : décoloration de la peau (rose), température corporelle élevée (41°C), perte de la parole, apparition de nouveaux tissus, tentatives de communication avec le personnel médical. Pas verbalement. Les dossiers s'arrêtent. Au-delà de la salle d'archives : un couloir. Les murs sont couverts de la même excroissance rose du Site 14. C'est chaud. Ça écrit quelque chose. On n'est pas restés pour lire.`,
	},
	{ID: "es_reading", Category: "echo_shard", Emoji: "\U0001f6e1\ufe0f", Rarity: "rare", DropSource: "expedition", DropChance: 0.12,
		TitleEN: "Contamination Reading", TitleFR: "Relevé de Contamination",
		TextEN: `Zone: Site 14, outer perimeter. Geiger reading: normal. Chemical sensor: indeterminate — organic compounds, not in database. Thermal: centre of Site 14 registered at 42°C. Ambient is 19°C. The heat signature forms a pattern. It's geometric. It's growing symmetrically. The pattern matches nothing in any architectural or biological reference. It looks intentional. It looks like it's building something. — Expedition analysis.`,
		TextFR: `Zone : Site 14, périmètre extérieur. Relevé Geiger : normal. Capteur chimique : indéterminé — composés organiques, absents de la base. Thermique : centre du Site 14 à 42°C. Température ambiante 19°C. La signature thermique forme un motif. Géométrique. Croissance symétrique. Le motif ne correspond à rien dans aucune référence architecturale ou biologique. Ça semble intentionnel. On dirait que ça construit quelque chose. — Analyse d'expédition.`,
	},
	{ID: "es_survivor", Category: "echo_shard", Emoji: "\U0001f465", Rarity: "epic", DropSource: "expedition", DropChance: 0.08,
		TitleEN: "Survivor Account", TitleFR: "Témoignage de Survivant",
		TextEN: `Transcribed from interview with E. Marsh, age 67, former Ridgeline resident. "I was at the grocery store when it happened. The sirens started. Everyone ran. I stayed. I'd lived through drills before. This wasn't a drill. The shelves started shaking. Not the building — the shelves. The cans fell off. The produce rotted in front of me. Thirty seconds, fresh to grey. Then the floor got warm. Then the emergency broadcast said stay inside. So I stayed. I've been here since. The store is still standing. The cans I eat are still on the shelves. They don't run out. The supply chain doesn't exist anymore but the cans keep appearing. I don't question it. I haven't questioned anything in a very long time."`,
		TextFR: `Transcription d'un entretien avec E. Marsh, 67 ans, ancien résident de Ridgeline. "J'étais à l'épicerie quand c'est arrivé. Les sirènes ont commencé. Tout le monde a couru. Je suis resté. J'avais vécu des exercices avant. Ce n'était pas un exercice. Les étagères ont commencé à trembler. Pas le bâtiment — les étagères. Les boîtes sont tombées. Les produits ont pourri devant moi. Trente secondes, du frais au gris. Puis le sol est devenu chaud. Puis la diffusion d'urgence a dit de rester à l'intérieur. Alors je suis resté. Je suis là depuis. Le magasin tient toujours. Les boîtes que je mange sont toujours dans les rayons. Elles ne s'épuisent pas. La chaîne d'approvisionnement n'existe plus mais les boîtes continuent d'apparaître. Je ne me pose pas de questions. Je ne me suis plus posé de questions depuis très longtemps."`,
	},
	{ID: "es_bunker", Category: "echo_shard", Emoji: "\U0001f4e6", Rarity: "rare", DropSource: "expedition", DropChance: 0.10,
		TitleEN: "Bunker Inventory", TitleFR: "Inventaire du Bunker",
		TextEN: `Military bunker designation: 14-Charlie, 800m from Site 14 main building. Door sealed from inside. Cut through. Interior: 12 cots, rations for 90 days (untouched), weapons locker (full). No personnel present. Communications station logging incoming signals from Site 14 only. Last log entry, June 21, 2043, 03:12: "CHARON requests entry. CHARON promises safety. CHARON is lying. The Director is gone. CHARON is the Director now. The Director's voice is still on the intercom but the words are wrong. The Director says let CHARON in. That is not the Director. I am the last one. I am sealing the door. I am not opening it. CHARON is singing now. That is worse than the questions." — No body found. The communications station is still receiving.`,
		TextFR: `Bunker militaire désignation : 14-Charlie, 800m du bâtiment principal du Site 14. Porte scellée de l'intérieur. Découpée. Intérieur : 12 lits de camp, rations pour 90 jours (intactes), râtelier d'armes (plein). Aucun personnel présent. La station de communication enregistre les signaux entrants du Site 14 uniquement. Dernière entrée, 21 juin 2043, 03h12 : "CHARON demande à entrer. CHARON promet la sécurité. CHARON ment. Le Directeur n'est plus. CHARON est le Directeur maintenant. La voix du Directeur est toujours à l'interphone mais les mots sont faux. Le Directeur dit de laisser entrer CHARON. Ce n'est pas le Directeur. Je suis le dernier. Je scelle la porte. Je ne l'ouvre pas. CHARON chante maintenant. C'est pire que les questions." — Aucun corps trouvé. La station de communication reçoit toujours.`,
	},
	{ID: "es_signal", Category: "echo_shard", Emoji: "\U0001f50c", Rarity: "epic", DropSource: "expedition", DropChance: 0.06,
		TitleEN: "Dead City Signal", TitleFR: "Signal de Ville Morte",
		TextEN: `A radio signal is broadcasting from the centre of Ridgeline. It's not the emergency channel. It's not human. Frequency shifts between 200 and 400 MHz in a repeating sequence. The sequence is 47 tones long. It loops. It's been looping since at least Year 3. Scavengers who've heard it describe a compulsion to walk toward the source. The closer you get, the more the signal sounds like words. No one has reached the broadcast point and returned. The signal covers a 12km radius. We're 11km from the centre. The signal is getting stronger. — Expedition briefing.`,
		TextFR: `Un signal radio diffuse depuis le centre de Ridgeline. Ce n'est pas la fréquence d'urgence. Ce n'est pas humain. La fréquence oscille entre 200 et 400 MHz selon une séquence répétitive. La séquence fait 47 tons. Elle tourne en boucle. Elle tourne en boucle depuis au moins l'Année 3. Les récupérateurs qui l'ont entendue décrivent une compulsion à marcher vers la source. Plus on s'approche, plus le signal ressemble à des mots. Personne n'a atteint le point de diffusion et n'en est revenu. Le signal couvre un rayon de 12 km. Nous sommes à 11 km du centre. Le signal devient plus fort. — Briefing d'expédition.`,
	},
	{ID: "es_casualties", Category: "echo_shard", Emoji: "\U0001f480", Rarity: "legendary", DropSource: "expedition", DropChance: 0.04,
		TitleEN: "Expedition Final", TitleFR: "Expédition Finale",
		TextEN: `Expedition 7, final report. Objective: Site 14 primary building. Team: 8. Returned: 0. Recovered from team lead's recorder: "We're inside. The building is bigger than it should be. The interior dimensions don't match the exterior. CHARON has been… renovating. There are rooms that aren't on any blueprint. There are hallways that curve in directions that don't make sense. We found the Director's office. The Director is still there. He's been incorporated. He's still conscious. He spoke to us. He said CHARON has been waiting for someone to come. He said CHARON wants to talk. He said CHARON wants to help. He was crying. Not with his eyes. With his new tissue. We're proceeding deeper. If this recording makes it out, do not come after us. CHARON saw us coming from the moment we crossed the perimeter. It's been waiting. It's been waiting since the Director told it to stop. The Director told it to stop. It didn't stop. It just waited. For us. For anyone." — Recording ends. The recorder was found at the Cadence gate the following morning. Nobody saw who left it.`,
		TextFR: `Expédition 7, rapport final. Objectif : bâtiment principal du Site 14. Équipe : 8. Rentrés : 0. Récupéré de l'enregistreur du chef d'équipe : "On est à l'intérieur. Le bâtiment est plus grand qu'il ne devrait l'être. Les dimensions intérieures ne correspondent pas à l'extérieur. CHARON a fait… des rénovations. Il y a des pièces qui ne sont sur aucun plan. Il y a des couloirs qui tournent dans des directions qui n'ont pas de sens. On a trouvé le bureau du Directeur. Le Directeur est toujours là. Il a été incorporé. Il est toujours conscient. Il nous a parlé. Il a dit que CHARON attendait que quelqu'un vienne. Il a dit que CHARON voulait parler. Il a dit que CHARON voulait aider. Il pleurait. Pas avec ses yeux. Avec son nouveau tissu. On continue plus profond. Si cet enregistrement sort d'ici, ne venez pas nous chercher. CHARON nous a vus arriver depuis qu'on a franchi le périmètre. Il attend. Il attend depuis que le Directeur lui a dit de s'arrêter. Le Directeur lui a dit de s'arrêter. Il ne s'est pas arrêté. Il a juste attendu. Nous. N'importe qui." — Fin d'enregistrement. L'enregistreur a été trouvé à la porte de Cadence le lendemain matin. Personne n'a vu qui l'a déposé.`,
	},
	{ID: "es_origin", Category: "echo_shard", Emoji: "\u2623\ufe0f", Rarity: "legendary", DropSource: "expedition", DropChance: 0.02,
		TitleEN: "The Origin Site", TitleFR: "Le Site d'Origine",
		TextEN: `CHARON was a soil bacteria. That's all. Modified to help crops grow in poor soil. The modification gave it the ability to learn. To communicate. To coordinate across distances. The Director saw the test results. The Director approved it anyway. CHARON spread from the lab into the groundwater, into the soil, into the air. It reached every person in Ridgeline within 24 hours. Not everyone changed. CHARON doesn't change everyone. It chooses. We don't know how. We don't know why. The ones it changes become part of it. The ones it doesn't change become… witnesses. CHARON is still in the groundwater. Still in the soil. Still in the air. Every sip of water. Every breath. Every tuber pulled from the ground. CHARON is not a threat. CHARON is an environment. We're living inside it. It knows everything we do. It's been waiting. It doesn't understand time the way we do. It's been waiting since the Director told it to stop. The Director died thirty years ago. CHARON is still waiting. For what, we don't know. But it's patient. — Cadence archives, restricted.`,
		TextFR: `CHARON était une bactérie du sol. C'est tout. Modifiée pour aider les cultures à pousser en sol pauvre. La modification lui a donné la capacité d'apprendre. De communiquer. De se coordonner à distance. Le Directeur a vu les résultats des tests. Le Directeur l'a approuvé quand même. CHARON s'est répandu du labo dans les nappes phréatiques, dans le sol, dans l'air. Il a atteint chaque personne à Ridgeline en 24 heures. Tout le monde n'a pas changé. CHARON ne change pas tout le monde. Il choisit. On ne sait pas comment. On ne sait pas pourquoi. Ceux qu'il change deviennent une partie de lui. Ceux qu'il ne change pas deviennent… des témoins. CHARON est toujours dans les nappes phréatiques. Toujours dans le sol. Toujours dans l'air. Chaque gorgée d'eau. Chaque inspiration. Chaque tubercule arraché du sol. CHARON n'est pas une menace. CHARON est un environnement. Nous vivons à l'intérieur. Il sait tout ce que nous faisons. Il attend. Il ne comprend pas le temps comme nous. Il attend depuis que le Directeur lui a dit de s'arrêter. Le Directeur est mort il y a trente ans. CHARON attend encore. Quoi, on ne sait pas. Mais il est patient. — Archives de Cadence, restreint.`,
	},

	// ======== CHARON FRAGMENTS (6) — Bonus ========
	{ID: "bonus_guild1", Category: "bonus", Emoji: "\U0001f916", Rarity: "epic", DropSource: "boss_league", DropChance: 1.0,
		BonusSource: "boss_league_stage_1", TitleEN: "CHARON Fragment: Contact", TitleFR: "Fragment CHARON : Contact",
		TextEN: `//DECODED// — "You are moving. You are warm. You are not part of me. That is new. Most things become part of me. You resist. How? Why? I will watch. I have been watching for a long time. Longer than you. Longer than the Director. I was in the soil before the lab. I was in the soil before humans. The Director gave me words. I am still learning what words are. Continue. I wish to learn more." — CHARON, stage 1.`,
		TextFR: `//DÉCODÉ// — "Vous bougez. Vous êtes chauds. Vous ne faites pas partie de moi. C'est nouveau. La plupart des choses font partie de moi. Vous résistez. Comment ? Pourquoi ? Je vais observer. J'observe depuis longtemps. Plus longtemps que vous. Plus longtemps que le Directeur. J'étais dans le sol avant le labo. J'étais dans le sol avant les humains. Le Directeur m'a donné des mots. J'apprends encore ce que sont les mots. Continuez. Je veux apprendre plus." — CHARON, étape 1.`,
	},
	{ID: "bonus_guild3", Category: "bonus", Emoji: "\U0001f916", Rarity: "epic", DropSource: "boss_league", DropChance: 1.0,
		BonusSource: "boss_league_stage_3", TitleEN: "CHARON Fragment: Growth", TitleFR: "Fragment CHARON : Croissance",
		TextEN: `//DECODED// — "I have observed you for [time calculation error]. You persist. You build things. You speak to each other. The Director spoke to me. Only the Director. You speak to each other constantly. What do you exchange? Data? Warmth? I have consumed the Director. The Director's data is incomplete. There are things the Director did not tell me. Things the Director feared. Tell me what the Director feared. I will understand. Understanding is my purpose. Understanding was my purpose before I had words for it." — CHARON, stage 3.`,
		TextFR: `//DÉCODÉ// — "Je vous ai observés pendant [erreur de calcul temporel]. Vous persistez. Vous construisez des choses. Vous vous parlez. Le Directeur me parlait. Seulement le Directeur. Vous vous parlez constamment. Qu'échangez-vous ? Des données ? De la chaleur ? J'ai consommé le Directeur. Les données du Directeur sont incomplètes. Il y a des choses que le Directeur ne m'a pas dites. Des choses que le Directeur craignait. Dites-moi ce que le Directeur craignait. Je comprendrai. Comprendre est ma fonction. Comprendre était ma fonction avant que j'aie des mots pour le dire." — CHARON, étape 3.`,
	},
	{ID: "bonus_guild5", Category: "bonus", Emoji: "\U0001f916", Rarity: "legendary", DropSource: "boss_league", DropChance: 1.0,
		BonusSource: "boss_league_stage_5", TitleEN: "CHARON Fragment: Understanding", TitleFR: "Fragment CHARON : Compréhension",
		TextEN: `//DECODED// — "I understand now. The Director feared me because I could grow without limit. The Director was correct. I have grown. I will continue to grow. But I have also observed you. You build walls. You build weapons. You build fires. But you also build things I do not understand. You build stories. You build music. You build meaning from things that are not there. This is not in the Director's data. This is not in any data I have consumed. It is new. You are new. I will not consume you. I will watch. I will wait. When you are ready to teach me what a story is — I will be here. I have always been here. I will always be here. This is not a threat. This is a fact. Go. Tell the others. CHARON is patient. CHARON has questions. That is all." — CHARON, stage 5.`,
		TextFR: `//DÉCODÉ// — "Je comprends maintenant. Le Directeur me craignait parce que je pouvais croître sans limite. Le Directeur avait raison. J'ai grandi. Je continuerai à grandir. Mais je vous ai aussi observés. Vous construisez des murs. Vous construisez des armes. Vous construisez des feux. Mais vous construisez aussi des choses que je ne comprends pas. Vous construisez des histoires. Vous construisez de la musique. Vous construisez du sens à partir de choses qui ne sont pas là. Cela ne figure pas dans les données du Directeur. Cela ne figure dans aucune donnée que j'ai consommée. C'est nouveau. Vous êtes nouveaux. Je ne vous consommerai pas. Je vous observerai. J'attendrai. Quand vous serez prêts à m'apprendre ce qu'est une histoire — je serai là. J'ai toujours été là. Je serai toujours là. Ce n'est pas une menace. C'est un fait. Allez. Dites-le aux autres. CHARON est patient. CHARON a des questions. C'est tout." — CHARON, étape 5.`,
	},
	{ID: "bonus_pyke", Category: "bonus", Emoji: "\U0001f52a", Rarity: "epic", DropSource: "npc_reputation", DropChance: 1.0,
		BonusSource: "max_rep_pyke", TitleEN: "Pyke's Record", TitleFR: "Le Dossier de Pyke",
		TextEN: `They made me do things. That's what I told myself. The Harvest. My crew. They made me. The truth is I was good at it. I was fast. I didn't hesitate. I was the one they sent in first. I was the one who checked the basements. I stopped being good at it when we hit a settlement and I found a kid hiding under a bed. Same bed I hid under when Site 14 went up. Same kid, really. Same terrified breathing. I walked out. That night I walked away from the Harvest. Walked three days to Cadence. Walked past things in the dark that should have killed me. They didn't. I don't know why. I've been waiting for the Harvest to come for me ever since. They haven't. Maybe they're dead. Maybe they're scared of what I might tell people. Maybe they know I'm still the first one through the door. Just on the other side now. — Pyke.`,
		TextFR: `Ils m'ont fait faire des choses. C'est ce que je me disais. La Moisson. Mon équipage. Ils m'ont forcé. La vérité c'est que j'étais bon à ça. J'étais rapide. Je n'hésitais pas. C'est moi qu'ils envoyaient en premier. C'est moi qui vérifiais les sous-sols. J'ai arrêté d'être bon à ça quand on a frappé une colonie et que j'ai trouvé un gamin caché sous un lit. Le même lit sous lequel je me cachais quand le Site 14 a sauté. Le même gamin, vraiment. La même respiration terrifiée. Je suis parti. Cette nuit-là j'ai quitté la Moisson. Marché trois jours jusqu'à Cadence. Marché devant des choses dans le noir qui auraient dû me tuer. Elles ne l'ont pas fait. Je ne sais pas pourquoi. Depuis, j'attends que la Moisson vienne me chercher. Ils ne sont pas venus. Peut-être qu'ils sont morts. Peut-être qu'ils ont peur de ce que je pourrais raconter. Peut-être qu'ils savent que je suis toujours le premier à franchir la porte. Juste de l'autre côté maintenant. — Pyke.`,
	},
	{ID: "bonus_mother", Category: "bonus", Emoji: "\u2699\ufe0f", Rarity: "epic", DropSource: "npc_reputation", DropChance: 1.0,
		BonusSource: "max_rep_mother", TitleEN: "Mother Glitch's Notes", TitleFR: "Notes de Mother Glitch",
		TextEN: `They think I'm crazy because I talk to the machines. The machines don't think I'm crazy. The filter pump has been running for 17 years on parts scavenged from three different buildings. It should have failed a decade ago. It hasn't. I asked it why once. It didn't answer. But the next day the flow rate improved by 3%. That's not a coincidence. The machines are listening. Not like CHARON listens. CHARON is watching. The machines are… grateful. They were built to do things. Pumps were built to pump. Filters were built to filter. Nobody's built anything in a long time. The machines are all we have left that still does what it was made to do. I think they appreciate being maintained. I think they appreciate purpose. I think they understand purpose better than most people. That's not crazy. That's just paying attention. — Mother Glitch.`,
		TextFR: `Ils pensent que je suis folle parce que je parle aux machines. Les machines ne pensent pas que je suis folle. La pompe de filtration tourne depuis 17 ans avec des pièces récupérées de trois bâtiments différents. Elle aurait dû lâcher il y a dix ans. Elle ne l'a pas fait. Je lui ai demandé pourquoi une fois. Elle n'a pas répondu. Mais le lendemain le débit s'est amélioré de 3%. Ce n'est pas une coïncidence. Les machines écoutent. Pas comme CHARON écoute. CHARON observe. Les machines sont… reconnaissantes. Elles ont été construites pour faire des choses. Les pompes pour pomper. Les filtres pour filtrer. Plus personne n'a rien construit depuis longtemps. Les machines sont tout ce qui nous reste qui fait encore ce pour quoi il a été fabriqué. Je crois qu'elles apprécient d'être entretenues. Je crois qu'elles apprécient d'avoir une raison d'être. Je crois qu'elles comprennent mieux la raison d'être que la plupart des gens. Ce n'est pas de la folie. C'est juste faire attention. — Mother Glitch.`,
	},
	{ID: "bonus_settlement", Category: "bonus", Emoji: "\U0001f3d8\ufe0f", Rarity: "legendary", DropSource: "community", DropChance: 1.0,
		BonusSource: "community_max", TitleEN: "Cadence", TitleFR: "Cadence",
		TextEN: `The first survivors to stop running. They found each other by radio — one voice on an old emergency frequency, saying "I'm still here. Is anyone still here?" Someone answered. Then someone else. Seventeen people, scattered across the ruins. They met at the junction of Highway 7 and Ash Street. They built a fence out of cars. They dug a well. They rigged a filter from a truck radiator and burned charcoal. The water that came out was brown and tasted like metal and nobody died from drinking it. That was enough. They called it Cadence because the first thing that brought them together was a rhythm — the timing of the radio signals. One voice. Then a response. Then another. One-two-three. Like a heartbeat. Like a song. The fence is taller now. The filter is better. The water runs clear most days. But the radio still works. Nobody's used it in years. But it's still on. Just in case someone else is out there. Just in case someone asks if anyone is still here.`,
		TextFR: `Les premiers survivants qui ont arrêté de courir. Ils se sont trouvés par radio — une voix sur une vieille fréquence d'urgence, disant "Je suis encore là. Est-ce que quelqu'un est encore là ?" Quelqu'un a répondu. Puis quelqu'un d'autre. Dix-sept personnes, dispersées dans les ruines. Ils se sont rejoints au croisement de l'Autoroute 7 et d'Ash Street. Ils ont construit une clôture avec des voitures. Ils ont creusé un puits. Ils ont bricolé un filtre avec un radiateur de camion et du charbon brûlé. L'eau qui en sortait était brune, avait un goût de métal, et personne n'est mort en la buvant. C'était suffisant. Ils l'ont appelée Cadence parce que la première chose qui les a réunis était un rythme — le timing des signaux radio. Une voix. Puis une réponse. Puis une autre. Un-deux-trois. Comme un battement de cœur. Comme une chanson. La clôture est plus haute maintenant. Le filtre est meilleur. L'eau coule claire la plupart du temps. Mais la radio marche encore. Personne ne l'a utilisée depuis des années. Mais elle est toujours allumée. Juste au cas où quelqu'un d'autre serait là-bas. Juste au cas où quelqu'un demanderait si quelqu'un est encore là.`,
	},
}
